  foreach($destinationLength in @(-1,4)){foreach($offset in @(-1,0,4,5,2147483647)){foreach($index in @(-1,0)){Request Bytes $units $index $length $destinationLength $offset $flush $pending}}}
 }
 foreach($units in $inputs){foreach($capacity in @(0,1,2,3,4,5,8)){foreach($offset in @(0,1)){Request Bytes ([int[]]$units) 0 $units.Length ($capacity+$offset) $offset $flush $pending}}}
}}
