 foreach($requestId in 0..($requests.Count-1)){$request=$requests[$requestId];$encoder=$encoding.GetEncoder();if($request.pending){[void]$encoder.GetBytes([char[]]@(0xd800),0,1,[byte[]]::new(8),0,$false)};$destination=$null;if($request.destinationLength -ge 0){$destination=[byte[]]::new([int]$request.destinationLength);[Array]::Fill[byte]($destination,99)}
