  $rows.Add([ordered]@{request=$requestId;result=$result;after=$(if($null -eq $destination -or $request.operation -eq 'Count'){$null}else{,[int[]]$destination});recovery=$recoverResult;recoveryAfter=[int[]]$recovery})
